import * as T from 'three';import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
export function createCity(container){
 const scene=new T.Scene();scene.background=new T.Color(0xdfe6d6);const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;container.appendChild(renderer.domElement);
 const camera=new T.OrthographicCamera(-15,15,12,-12,.1,150);camera.position.set(23,24,30);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(3,0,0);controls.enablePan=false;controls.minZoom=.7;controls.maxZoom=1.8;controls.maxPolarAngle=1.25;controls.addEventListener('change',render);controls.update();
 const light=new T.DirectionalLight(0xffddb3,3.1);light.position.set(-10,20,10);light.castShadow=true;light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-20,right:20,top:20,bottom:-20,near:.5,far:80});light.shadow.normalBias=.03;light.shadow.bias=-.0001;scene.add(light,new T.HemisphereLight(0xe8f2ff,0x89906c,2));
 const geometry=new T.BoxGeometry(1,1,1),mats=new Map();function box(x,y,z,w,h,d,c,parent=scene){if(!mats.has(c))mats.set(c,new T.MeshStandardMaterial({color:c,roughness:.88}));const m=new T.Mesh(geometry,mats.get(c));m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
 box(0,-.45,0,21,.75,18,0xa3b68d);box(0,.02,0,21,.2,3.4,0x6c7d79);box(0,.02,0,3.3,.2,18,0x6c7d79);for(let i=-9;i<=9;i+=3)box(i,.13,0,1.1,.02,.1,0xe7e4c9);for(let i=-7;i<=7;i+=3)box(0,.14,i,.1,.02,1.1,0xe7e4c9);
 function building(x,z,w,d,h,color,trim,name){box(x,.22,z,w+1,.3,d+1,0xd6d2bd);box(x,h/2+.35,z,w,h,d,color);box(x,h+.4,z,w+.45,.35,d+.45,trim);box(x,.55,z,w+.15,.3,d+.15,trim);for(const dx of [-w/3,0,w/3]){box(x+dx,1.5,z+d/2+.05,.65,1.15,.12,0x365651);if(h>3)box(x+dx,3.1,z+d/2+.05,.65,.9,.12,0x365651);}box(x,2.25,z+d/2+.5,w+.5,.35,1,trim);box(x,2.22,z+d/2+1.02,2,.36,.06,0xeee0bb);
 const canvas=document.createElement('canvas');canvas.width=256;canvas.height=48;const ctx=canvas.getContext('2d');ctx.fillStyle='#eee0bb';ctx.fillRect(0,0,256,48);ctx.fillStyle='#294537';ctx.font='bold 28px sans-serif';ctx.textAlign='center';ctx.fillText(name,128,35);const tex=new T.CanvasTexture(canvas);tex.colorSpace=T.SRGBColorSpace;const sign=new T.Mesh(new T.PlaneGeometry(1.9,.33),new T.MeshBasicMaterial({map:tex}));sign.position.set(x,2.22,z+d/2+1.06);scene.add(sign);}
 building(-5,-4.7,4.8,3.4,4,0xc77b59,0x456e57,'MARKET');building(5,-4.7,4.1,3.6,4.8,0xe0c27c,0x627a81,'UTILITIES');building(-5,5,4.4,3.3,3.7,0xe2d5b3,0x567d6a,'HOME');building(5,5,4.9,3.5,2.7,0xb8c6ad,0xa66d51,'GARAGE');
 for(const [x,z] of [[-9,-6],[-9,3],[-8,7],[8,-7],[9,1],[9,7],[-3,-8]]){box(x,.45,z,1,.6,1,0xd4c49a);box(x,1.5,z,.18,2,.18,0x877253);box(x,2.8,z,1.35,1.1,1.25,0x718d55);box(x-.1,3.45,z-.1,1,.5,.9,0x8ca76c);}
 const unlock=new T.Group();scene.add(unlock);for(let i=0;i<5;i++){box(-8+i*.35,.4,-2.1,.22,.55,.22,i%2?0xdba75d:0xcc8061,unlock);}box(-2.3,1.5,-7,.14,3,.14,0x4f6b58,unlock);box(-2.3,3,-7,1.2,.65,.13,0xd9ed83,unlock);unlock.visible=false;
 const car=new T.Group();scene.add(car);const body=box(0,.48,0,1.7,.6,.85,0xe9b765,car);box(-.05,.94,0,.9,.45,.78,0x385c5b,car);for(const x of [-.55,.55])for(const z of [-.47,.47])box(x,.25,z,.32,.32,.13,0x354c3e,car);car.position.set(-5,0,0);const stripe=box(0,.8,0,1.65,.025,.16,0xeee2b7,car);stripe.visible=false;
 function render(){renderer.render(scene,camera);}function resize(){const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h);const ratio=w/h,span=w<700?14:12;camera.left=-span*ratio;camera.right=span*ratio;camera.top=span;camera.bottom=-span;camera.updateProjectionMatrix();render();}new ResizeObserver(resize).observe(container);resize();
 let animation=0;return {update(state){unlock.visible=state.rewarded;stripe.visible=!!state.equipped;body.material=state.equipped?new T.MeshStandardMaterial({color:0xdaa658,roughness:.9}):mats.get(0xe9b765);render();},reset(){camera.position.set(23,24,30);camera.zoom=1;controls.target.set(3,0,0);controls.update();resize();},travel(reduced=false){cancelAnimationFrame(animation);if(reduced){car.position.x=5;render();return;}const start=performance.now();function tick(now){const t=Math.min((now-start)/2000,1);car.position.x=-5+10*t;render();if(t<1)animation=requestAnimationFrame(tick);}animation=requestAnimationFrame(tick);}};
}
